#include <stdio.h>
#include <stdlib.h>
#define MAX_SIZE 100
int top = -1;
long stack[MAX_SIZE];
void push(long value) {
    if (top < MAX_SIZE - 1) {
        stack[++top] = value;
    }
}
long pop() {
    if (top >= 0) {
        return stack[top--];
    }
    return 0;
}
int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <postfix_expression>\n", argv[0]);
        return 1;
    }
    for (int i = 1; i < argc; i++) {
        char *arg = argv[i];
        if (arg[0] == '+') {
            long b = pop();
            long a = pop();
            push(a + b);
        } else if (arg[0] == '-') {
            long b = pop();
            long a = pop();
            push(a - b);
        } else if (arg[0] == '*') {
            long b = pop();
            long a = pop();
            push(a * b);
        } else if (arg[0] == '/') {
            long b = pop();
            long a = pop();
            push(a / b);
        } else {
            char *endptr;
            long value = strtol(arg, &endptr, 10);
            if (*endptr != '\0') {
                printf("Invalid input: %s\n", arg);
                return 1;
            }
            push(value);
        }
    }
    if (top != 0) {
        printf("Invalid postfix expression\n");
        return 1;
    }
    printf("%ld\n", pop());
    return 0;
}
